sys_script_include.script:
var AdmissionMeritEngine = Class.create();
AdmissionMeritEngine.prototype = {
    initialize: function() {},

    /**
     * Calculates composite merit score: (10th% + 12th% + JEE) / 3
     */
    calculateMeritScore: function(arg1, arg2, arg3) {
        var m10 = 0, m12 = 0, jee = 0;
        if (typeof arg1 === 'number' || typeof arg1 === 'string') {
            m10 = parseFloat(arg1) || 0;
            m12 = parseFloat(arg2) || 0;
            jee = parseFloat(arg3) || 0;
        } else if (arg1 && typeof arg1.isValidRecord === 'function' && arg1.isValidRecord()) {
            m10 = parseFloat(arg1.getValue('class_10_percentage')) || 0;
            m12 = parseFloat(arg1.getValue('class_12_percentage')) || 0;
            jee = parseFloat(arg1.getValue('jee_score')) || 0;
        }
        var composite = (m10 + m12 + jee) / 3;
        return parseFloat(composite.toFixed(2));
    },

    /**
     * 5-Tier Tie-Breaker Comparison:
     * Tier 1: Composite Merit Score (Highest first)
     * Tier 2: JEE Score (Highest first)
     * Tier 3: Class 12 Percentage (Highest first)
     * Tier 4: Class 10 Percentage (Highest first)
     * Tier 5: Seniority by DOB (Older first: earlier DOB string < later DOB string)
     */
    compareApplicants: function(a, b) {
        var meritA = a.merit !== undefined ? a.merit : (parseFloat(a.merit_score) || 0);
        var meritB = b.merit !== undefined ? b.merit : (parseFloat(b.merit_score) || 0);
        if (meritB !== meritA) return meritB - meritA;

        var jeeA = a.jee !== undefined ? a.jee : (parseFloat(a.jee_score) || 0);
        var jeeB = b.jee !== undefined ? b.jee : (parseFloat(b.jee_score) || 0);
        if (jeeB !== jeeA) return jeeB - jeeA;

        var m12A = a.m12 !== undefined ? a.m12 : (parseFloat(a.class_12_percentage) || 0);
        var m12B = b.m12 !== undefined ? b.m12 : (parseFloat(b.class_12_percentage) || 0);
        if (m12B !== m12A) return m12B - m12A;

        var m10A = a.m10 !== undefined ? a.m10 : (parseFloat(a.class_10_percentage) || 0);
        var m10B = b.m10 !== undefined ? b.m10 : (parseFloat(b.class_10_percentage) || 0);
        if (m10B !== m10A) return m10B - m10A;

        var dobA = a.dob || a.date_of_birth || '';
        var dobB = b.dob || b.date_of_birth || '';
        if (dobA && dobB) {
            return dobA < dobB ? -1 : (dobA > dobB ? 1 : 0);
        }

        return 0;
    },

    sortCandidates: function(list) {
        var self = this;
        list.sort(function(a, b) { return self.compareApplicants(a, b); });
        return list;
    },

    /**
     * Ranks ALL verified applicants across the university
     */
    rankAllVerifiedApplicants: function() {
        var gr = new GlideRecord('x_1790229_edusph_0_admission_application');
        var statQc = gr.addQuery('status', 'CONTAINS', 'verified');
        statQc.addOrCondition('status', 'in_merit');
        statQc.addOrCondition('status', 'in merit');
        gr.query();

        var list = [];
        while (gr.next()) {
            var m10Val = gr.getValue('class_10_percentage');
            var m12Val = gr.getValue('class_12_percentage');
            var jeeVal = gr.getValue('jee_score');
            var dobVal = gr.getValue('date_of_birth') || '';

            var isIncomplete = (!m10Val || !m12Val || !jeeVal || !dobVal);
            var merit = this.calculateMeritScore(gr);

            list.push({
                sys_id: gr.getUniqueValue(),
                app_no: gr.getValue('app_no'),
                name: gr.getValue('name'),
                category: gr.getValue('category'),
                merit: merit,
                jee: parseFloat(jeeVal) || 0,
                m10: parseFloat(m10Val) || 0,
                m12: parseFloat(m12Val) || 0,
                dob: dobVal,
                incomplete: isIncomplete
            });
        }

        var self = this;
        list.sort(function(a, b) { return self.compareApplicants(a, b); });

        // Update calculated merit scores on applications
        for (var i = 0; i < list.length; i++) {
            var upd = new GlideRecord('x_1790229_edusph_0_admission_application');
            if (upd.get(list[i].sys_id)) {
                upd.setValue('merit_score', list[i].merit);
                if (upd.getValue('status') === 'verified') {
                    upd.setValue('status', 'in_merit');
                }
                upd.update();
            }
        }

        return list;
    },

    /**
     * Backwards-compatible program-specific ranking
     */
    rankApplicants: function(collegeId, programId) {
        return this.rankAllVerifiedApplicants();
    },

    type: 'AdmissionMeritEngine'
};
